+// Sales from the till: each dish sold uses one recipe portion per quantity.
+// Sale lines are kept in `store.data.sales` (ticket, soldAt, dishId, qty).
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+import { getItem } from "./items.js";
+
+/**
+ * Records sale lines { row, ticket, soldAt, dishId, qty } and consumes their
+ * ingredients (ref `sale:<ticket>`, at the sale time). Tickets already
+ * imported are skipped. All or nothing: a failure throws bad_request naming
+ * the row (`line.row`) and leaves the store unchanged.
+ * Returns { tickets, dishes } for what was imported.
+ */
+export function importSales(store, lines) {
+  const known = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const snapshot = structuredClone(store.data);
+  const imported = new Set();
+  let dishes = 0;
+  let current = null;
+  try {
+    for (const line of lines) {
+      current = line;
+      if (known.has(line.ticket)) continue;
+      const dish = getDish(store, line.dishId);
+      for (const n of scaled(getRecipe(store, dish.recipeId), line.qty))
+        consume(store, n.itemId, n.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+      store.data.sales ??= [];
+      store.data.sales.push({ ticket: line.ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty });
+      imported.add(line.ticket);
+      dishes += line.qty;
+    }
+  } catch (e) {
+    store.data = snapshot;
+    if (e instanceof AppError && e.code === "not_enough_stock")
+      throw new AppError("bad_request", {
+        reason: `${current.row}: only ${e.params.available} ${e.params.unit} of ${e.params.item} left`,
+      });
+    throw e;
+  }
+  return { tickets: imported.size, dishes };
+}
+
+/** Per item, theoretical use (from sales) and actual use (consume movements) between two days, inclusive. */
+export function varianceReport(store, from, to) {
+  const rows = new Map();
+  const row = (itemId) => {
+    if (!rows.has(itemId)) rows.set(itemId, { theoretical: 0, actual: 0 });
+    return rows.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    const day = dayOf(s.soldAt);
+    if (day < from || day > to) continue;
+    const dish = store.data.dishes?.find((d) => d.id === s.dishId);
+    const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) row(n.itemId).theoretical += n.qty;
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId !== undefined) row(itemId).actual += m.qty;
+  }
+  const r3 = (x) => Math.round(x * 1000) / 1000;
+  return [...rows]
+    .filter(([, v]) => v.theoretical > 0 || v.actual > 0)
+    .sort((a, b) => a[0] - b[0])
+    .map(([itemId, v]) => ({
+      itemId,
+      name: getItem(store, itemId).name,
+      theoretical: r3(v.theoretical),
+      actual: r3(v.actual),
+      difference: r3(v.actual - v.theoretical),
+    }));
+}
